return-response.set-body:
@{
                var min = 10;
                int.TryParse(context.Request.Url.Query.GetValueOrDefault("minDiscount", "10"), out min);
                if (min < 5) { min = 5; }
                if (min > 70) { min = 70; }
                var r = new Random();
                var names = new[] { "Tastiera meccanica", "Monitor 27 pollici", "Webcam 4K", "Docking station", "Cuffie ANC" };
                var items = new System.Text.StringBuilder("[");
                var count = 0;
                for (var i = 0; i < names.Length; i++) {
                    if (r.Next(0, 100) < 40) { continue; }
                    var cents = r.Next(2000, 50000);
                    var discount = r.Next(min, 71);
                    var finalCents = cents * (100 - discount) / 100;
                    if (count > 0) { items.Append(","); }
                    items.Append("{\"id\":\"P" + (100 + i) + "\",\"name\":\"" + names[i] + "\",\"listPrice\":" + (cents / 100) + "." + (cents % 100).ToString("00") + ",\"discountPercent\":" + discount + ",\"price\":" + (finalCents / 100) + "." + (finalCents % 100).ToString("00") + ",\"currency\":\"EUR\"}");
                    count++;
                }
                return items.Append("]").ToString();
            }
